<?php
namespace App\Application\Claims;
use App\Application\Audit\AuditWriter;use App\Application\Events\OutboxWriter;use App\Models\{Claim,ClaimDecision,ClaimPayment,User};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;
final class ClaimPaymentService{public function __construct(private AuditWriter$audit,private OutboxWriter$outbox){}public function request(Claim$c,ClaimDecision$d,array$input,User$actor):ClaimPayment{return DB::transaction(function()use($c,$d,$input,$actor){$c=Claim::whereKey($c->id)->lockForUpdate()->firstOrFail();if($c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id()||$d->claim_id!==$c->id||$d->status!=='APPROVED')abort(404);if($input['payee_party_id']!==$c->claimant_party_id||!in_array($c->status,['APPROVED','PARTIALLY_APPROVED'],true)||$input['amount_minor']>$d->approved_amount_minor||$input['amount_minor']<=0)throw ValidationException::withMessages(['amount_minor'=>__('wave7.payment_invalid')]);if($x=ClaimPayment::where(['claim_id'=>$c->id,'idempotency_key'=>$input['idempotency_key']])->first())return$x;$p=ClaimPayment::create(['claim_id'=>$c->id,'claim_decision_id'=>$d->id,'payee_party_id'=>$input['payee_party_id'],'amount_minor'=>$input['amount_minor'],'currency'=>$c->currency,'status'=>'PENDING_APPROVAL','idempotency_key'=>$input['idempotency_key'],'requested_by'=>$actor->id,'claim_settlement_id'=>$input['claim_settlement_id']??null]);$this->audit->record('claim.payment.requested','claim_payment',$p->id,['claim_id'=>$c->id,'amount_minor'=>$p->amount_minor]);return$p;});}public function approve(ClaimPayment$p,User$actor):ClaimPayment{return DB::transaction(function()use($p,$actor){$p=ClaimPayment::whereKey($p->id)->lockForUpdate()->firstOrFail();$c=Claim::whereKey($p->claim_id)->lockForUpdate()->firstOrFail();if($c->tenant_id!==app(\App\Domain\Tenancy\TenantContext::class)->id()||$p->status!=='PENDING_APPROVAL'||$p->requested_by===$actor->id)throw ValidationException::withMessages(['status'=>__('wave7.approval_invalid')]);$p->update(['status'=>'APPROVED','approved_by'=>$actor->id,'approved_at'=>now()]);$c->update(['status'=>'PAYMENT_PENDING','version'=>$c->version+1]);$this->outbox->record('claim.payment.approved','claim_payment',$p->id,['claim_id'=>$c->id]);return$p->refresh();});}public function processing(ClaimPayment$p):ClaimPayment{$this->must($p,['APPROVED','RETRY_PENDING']);$p->update(['status'=>'PROCESSING','attempt_count'=>$p->attempt_count+1,'next_attempt_at'=>null]);return$p->refresh();}public function fail(ClaimPayment$p,string$reason):ClaimPayment{$this->must($p,['PROCESSING']);$p->update(['status'=>'RETRY_PENDING','failure_reason'=>$reason,'next_attempt_at'=>now()->addMinutes(5)]);return$p->refresh();}public function paid(ClaimPayment$p,string$reference):ClaimPayment{return DB::transaction(function()use($p,$reference){$p=ClaimPayment::whereKey($p->id)->lockForUpdate()->firstOrFail();$this->must($p,['PROCESSING']);$p->update(['status'=>'PAID','external_reference'=>$reference,'paid_at'=>now(),'failure_reason'=>null]);$c=Claim::whereKey($p->claim_id)->lockForUpdate()->firstOrFail();$c->update(['status'=>'PAID','version'=>$c->version+1]);$this->outbox->record('claim.payment.paid','claim_payment',$p->id,['claim_id'=>$c->id,'external_reference'=>$reference]);/* REQ-CLM-013: a settlement payment settles its obligation and posts claim.settlement.paid. */if($p->claim_settlement_id)app(\App\Application\Claims\Settlement\ClaimSettlementService::class)->onPaymentPaid($p,$reference);return$p->refresh();});}public function reverse(ClaimPayment$p,string$reason,User$actor):ClaimPayment{return DB::transaction(function()use($p,$reason,$actor){$p=ClaimPayment::whereKey($p->id)->lockForUpdate()->firstOrFail();$this->must($p,['PAID']);if($p->approved_by===$actor->id)throw ValidationException::withMessages(['actor'=>__('wave7.reversal_checker')]);$p->update(['status'=>'REVERSED','reversed_at'=>now(),'failure_reason'=>$reason]);$c=Claim::whereKey($p->claim_id)->lockForUpdate()->firstOrFail();$c->update(['status'=>'PAYMENT_PENDING','version'=>$c->version+1]);$this->audit->record('claim.payment.reversed','claim_payment',$p->id,['reason'=>$reason]);$this->outbox->record('claim.payment.reversed','claim_payment',$p->id,['claim_id'=>$c->id]);if($p->claim_settlement_id)app(\App\Application\Claims\Settlement\ClaimSettlementService::class)->onPaymentReversed($p,$reason);return$p->refresh();});}private function must(ClaimPayment$p,array$states):void{if(!in_array($p->status,$states,true))throw ValidationException::withMessages(['status'=>__('wave7.payment_state_invalid')]);}}
